import { useState } from "react";
import { Card } from "@/shared/ui/data/Card";
import { Button } from "@/shared/ui/controls/Button";
import { TextField } from "@/shared/ui/controls/Field";

export function WorkspaceCard() {
  const [bscBaseDir, setBscBaseDir] = useState("");

  // The real handler opens a native OS directory picker via `invoke("pick_directory")` (Tauri,
  // unresolvable in this sandbox) — stubbed to a plausible sample path.
  function chooseBaseDir() {
    setBscBaseDir("C:\\Users\\dev\\.base-studio-code");
  }

  return (
    <Card title="Workspace">
      <TextField
        label="Base directory"
        value={bscBaseDir}
        onChange={setBscBaseDir}
        placeholder="~/.base-studio-code"
        trailing={<Button onClick={chooseBaseDir}>Choose...</Button>}
        hint={<>
          Where projects, clones, and agent worktrees live
          (<code>&lt;base&gt;/projects/&lt;project&gt;/...</code>). Leave blank for the default
          (<code>~/.base-studio-code</code>).
        </>}
      />
    </Card>
  );
}
